"""Expand a bitfield into a 64-bit int (8 bool bytes)."""
def unpack_bits(byte: Any) -> object {
    longbits = byte & 255;
    longbits = (longbits | (longbits << 28)) & 64424509455;
    longbits = (longbits | (longbits << 14)) & 844437815230467;
    longbits = (longbits | (longbits << 7)) & 72340172838076673;
    return longbits;
}

