    Returns the passed val otherwise. Ignores case."""
def istruthy(val: Any) -> (bool or str or int or dict or list or None) {
    if not val {
        return val;
    } elif isinstance(val, bool) {
        return val;
    } elif isinstance(val, str) {
        return {'t': True, 'true': True, 'y': True, 'yes': True, '1': True}.get(
            str(val).strip().lower(), False
        );
    } elif isinstance(val, int) {
        return {1: True}.get(val, False);
    } else {
        return val;
    }
}

